func (q *Queries) StartedToolCalls(ctx context.Context) ([]ToolCall, error) {
	rows, err := q.db.QueryContext(ctx, startedToolCalls)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ToolCall
	for rows.Next() {
		var i ToolCall
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ProjectID,
			&i.ProcessID,
			&i.Actor,
			&i.Caller,
			&i.Tool,
			&i.Class,
			&i.Outcome,
			&i.Params,
			&i.ExternalID,
			&i.Error,
			&i.AskID,
			&i.Run,
			&i.Result,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const stopParkedProcess = `-- name: StopParkedProcess :execrows
UPDATE process SET state = ?, error = ?, error_type = ?, error_details = ?, finished_at = ?, deadline_ms = NULL, silent_since_ms = NULL
WHERE id = ? AND finished_at IS NULL
`

type StopParkedProcessParams struct {
	State        string
	Error        string
	ErrorType    string
	ErrorDetails string
	FinishedAt   sql.NullString
	ID           int64
}

func (q *Queries) StopParkedProcess(ctx context.Context, arg StopParkedProcessParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, stopParkedProcess,
		arg.State,
		arg.Error,
		arg.ErrorType,
		arg.ErrorDetails,
		arg.FinishedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const undoDecision = `-- name: UndoDecision :exec
UPDATE tool_call SET run = '' WHERE ask_id = ? AND run = 'running'
`

func (q *Queries) UndoDecision(ctx context.Context, askID sql.NullInt64) error {
	_, err := q.db.ExecContext(ctx, undoDecision, askID)
	return err
}
